IF OBJECT_ID('dbo.admission_audit','U') IS NOT NULL DROP TABLE dbo.admission_audit; IF OBJECT_ID('dbo.admissions','U') IS NOT NULL DROP TABLE dbo.admissions; IF OBJECT_ID('dbo.wards','U') IS NOT NULL DROP TABLE dbo.wards; CREATE TABLE dbo.wards(WardID int PRIMARY KEY,WardName nvarchar(100),BedCapacity int); CREATE TABLE dbo.admissions(AdmissionID int PRIMARY KEY,PatientName nvarchar(100),WardID int REFERENCES dbo.wards,WardStatus varchar(20) DEFAULT 'Admitted',AdmissionDate datetime2 DEFAULT SYSDATETIME()); CREATE TABLE dbo.admission_audit(AuditID int IDENTITY PRIMARY KEY,AdmissionID int,ActionName varchar(10),PatientName nvarchar(100),WardID int,WardStatus varchar(20),ChangedAt datetime2 DEFAULT SYSDATETIME(),ChangedBy sysname); INSERT dbo.wards VALUES(1,'General Ward',3),(2,'ICU',2); INSERT dbo.admissions VALUES(100,'Patient A',1,'Admitted',DEFAULT),(101,'Patient B',1,'Admitted',DEFAULT),(102,'Patient C',1,'Admitted',DEFAULT),(200,'Patient D',2,'Admitted',DEFAULT);